const premiumPlanId=value=>String(value||'').trim().toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-|-$/g,'').slice(0,40);
function cleanPremiumPlan(body,existing={}){
 const id=premiumPlanId(body.id||existing.id||body.name),name=String(body.name||existing.name||'Premium Plan').trim().slice(0,60);
 if(!id||!name)throw Error('Plan ID and name are required.');
 return{id,name,price:Math.max(0,Math.min(999,Number(body.price??existing.price)||0)),dailyAiLimit:Math.max(1,Math.min(500,Math.floor(Number(body.dailyAiLimit??existing.dailyAiLimit)||1))),wordLimit:Math.max(40,Math.min(2000,Math.floor(Number(body.wordLimit??existing.wordLimit)||80))),outputTokenLimit:Math.max(200,Math.min(8000,Math.floor(Number(body.outputTokenLimit??existing.outputTokenLimit)||350))),yearlyDiscount:Math.max(0,Math.min(80,Number(body.yearlyDiscount??existing.yearlyDiscount)||0)),description:String(body.description??existing.description??'').trim().slice(0,180),recommended:body.recommended===true,active:body.active!==false,order:Math.max(0,Math.min(999,Math.floor(Number(body.order??existing.order)||0)))};
}
