r.post('/api/admin/premium-plans',admin,superAdmin,async(req,res)=>{try{const items=await premiumPlans(getSettings),plan=cleanPremiumPlan(req.body);if(items.some(item=>item.id===plan.id))return res.status(409).json({message:'A package with this ID already exists.'});if(plan.recommended)items.forEach(item=>item.recommended=false);items.push(plan);await getSettings().updateOne({_id:'premium_plans'},{$set:{items,updatedAt:new Date(),updatedBy:req.admin.email}},{upsert:true});res.status(201).json({data:plan,message:'Premium package created.'})}catch(error){res.status(400).json({message:error.message||'Unable to create Premium package.'})}});
r.put('/api/admin/premium-plans/:id',admin,superAdmin,async(req,res)=>{try{const id=premiumPlanId(req.params.id),items=await premiumPlans(getSettings),index=items.findIndex(item=>item.id===id);if(index<0)return res.status(404).json({message:'Premium package not found.'});const plan=cleanPremiumPlan({...req.body,id},items[index]);if(plan.recommended)items.forEach(item=>item.recommended=false);items[index]=plan;await getSettings().updateOne({_id:'premium_plans'},{$set:{items,updatedAt:new Date(),updatedBy:req.admin.email}},{upsert:true});res.json({data:plan,message:'Premium package updated.'})}catch(error){res.status(400).json({message:error.message||'Unable to update Premium package.'})}});
r.delete('/api/admin/premium-plans/:id',admin,superAdmin,async(req,res)=>{try{const id=premiumPlanId(req.params.id),items=await premiumPlans(getSettings),next=items.filter(item=>item.id!==id);if(next.length===items.length)return res.status(404).json({message:'Premium package not found.'});if(!next.length)return res.status(400).json({message:'Keep at least one Premium package.'});await getSettings().updateOne({_id:'premium_plans'},{$set:{items:next,updatedAt:new Date(),updatedBy:req.admin.email}},{upsert:true});res.json({data:{id},message:'Premium package removed.'})}catch(error){res.status(500).json({message:'Unable to remove Premium package.'})}});
